package com.personal.assistant.module.automation.controller;import com.personal.assistant.common.response.ApiResponse;import com.personal.assistant.common.security.SecurityContextHelper;import com.personal.assistant.module.automation.dto.AutomationRuleRequest;import com.personal.assistant.module.automation.entity.*;import com.personal.assistant.module.automation.service.*;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/automation")public class AutomationController{private final AutomationService service;private final AutomationRetryService retries;public AutomationController(AutomationService service,AutomationRetryService retries){this.service=service;this.retries=retries;}private Long uid(){return SecurityContextHelper.currentUserId();}@GetMapping("/rules")public ApiResponse<List<AutomationRule>>list(){return ApiResponse.success(service.list(uid()));}@PostMapping("/rules")public ApiResponse<Long>create(@Valid @RequestBody AutomationRuleRequest r){return ApiResponse.success(service.create(uid(),r));}@PutMapping("/rules/{id}")public ApiResponse<Void>update(@PathVariable Long id,@Valid @RequestBody AutomationRuleRequest r){service.update(uid(),id,r);return ApiResponse.success();}@PatchMapping("/rules/{id}/enabled")public ApiResponse<Void>toggle(@PathVariable Long id,@RequestParam boolean enabled){service.toggle(uid(),id,enabled);return ApiResponse.success();}@PostMapping("/rules/{id}/run")public ApiResponse<Void>run(@PathVariable Long id){service.runNow(uid(),id);return ApiResponse.success();}@DeleteMapping("/rules/{id}")public ApiResponse<Void>delete(@PathVariable Long id){service.delete(uid(),id);return ApiResponse.success();}@GetMapping("/rules/{id}/executions")public ApiResponse<List<AutomationExecution>>logs(@PathVariable Long id){return ApiResponse.success(service.logs(uid(),id));}@PostMapping("/executions/{id}/retry")public ApiResponse<Void>retry(@PathVariable Long id){retries.retry(uid(),id);return ApiResponse.success();}}
